#include <stdlib.h>

typedef enum { SHAPE_CIRCLE, SHAPE_SQUARE } shape_kind;

typedef struct {
    shape_kind tag;
    union { double radius; double side; };   /* C11 anonymous union */
} shape;

double area(const shape *s) {
    switch (s->tag) {
    case SHAPE_CIRCLE: return 3.141592653589793 * s->radius * s->radius;
    case SHAPE_SQUARE: return s->side * s->side;
    }
    abort();                    /* unreachable while every enumerator is handled */
}
